fn cb_hack_php_119(s: &mut Scan<'_, '_>, m: &Match<'_>) -> Result<(), LexError> {
    let mut v_name = String::new();
    v_name = (&m.group(0).to_lowercase()).to_string();
    if v_name.as_str() == "use" {
        s.push("in_use")?;
        s.token(T::KEYWORD_NAMESPACE, m.text());
    } else {
        if v_name.as_str() == "const" {
            s.push("in_const")?;
            s.token(T::KEYWORD, m.text());
        } else {
            if v_name.as_str() == "catch" {
                s.push("in_catch")?;
                s.token(T::KEYWORD, m.text());
            } else {
                if contains(SET_114, v_name.as_str()) {
                    s.push("in_visibility")?;
                    s.token(T::KEYWORD, m.text());
                } else {
                    if v_name.as_str() == "stdClass" {
                        s.token(T::NAME_CLASS, m.text());
                    } else {
                        if contains(SET_115, v_name.as_str()) {
                            s.token(T::KEYWORD, m.text());
                        } else {
                            if search(1401, m.group(0)) {
                                s.token(T::NAME_BUILTIN, m.text());
                            } else {
                                if search(1402, m.group(0)) {
                                    s.token(T::KEYWORD_CONSTANT, m.text());
                                } else {
                                    if search(1403, m.group(0)) {
                                        s.token(T::NAME_CONSTANT, m.text());
                                    } else {
                                        if search(1404, m.group(0)) {
                                            s.token(T::NAME_CLASS, m.text());
                                        } else {
                                            s.token(T::NAME, m.text());
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    Ok(())
}

